    "allium_sativum.cultivar_groups.softneck.storage.shelf_life": "6 a 8 meses",
    "allium_sativum.harvest_sign": "Saca las plantas con cuidado con una horquilla de jardín cuando alrededor de la mitad del follaje se ponga café.",
    "amorpha_fruticosa.invasive_note": "Invasora fuera de su área de distribución natural.",
    "amorpha_fruticosa.invasive_regions": "la Unión Europea y el oeste de Estados Unidos",
    "basella_alba.harvest_sign": "Se recomienda cosechar a mano, cortando las hojas y los tallos tiernos, que son las partes más aprovechables de la planta.",
    "basella_alba.storage.caution": "Las temperaturas bajas (entre 30 y 40 °F) le causan daño por frío.",
